import{_ as e,o,c as s,ag as r}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Repair Station","description":"","frontmatter":{},"headers":[],"relativePath":"pt/repair-station/index.md","filePath":"pt/repair-station/index.md"}'),i={name:"pt/repair-station/index.md"};function t(n,a,p,d,c,l){return o(),s("div",null,[...a[0]||(a[0]=[r(`<h1 id="repair-station" tabindex="-1">Repair Station <a class="header-anchor" href="#repair-station" aria-label="Permalink to &quot;Repair Station&quot;">​</a></h1><p>Entra-se com o veículo numa estação de reparação, escolhe-se um serviço e o veículo é reparado no local: motor, carroçaria e pneus, com som e faíscas. O preço acompanha os danos, por isso um carro riscado paga menos do que um destroço. As estações colocam-se no jogo e cada definição edita-se no jogo.</p><h2 id="funcionalidades" tabindex="-1">Funcionalidades <a class="header-anchor" href="#funcionalidades" aria-label="Permalink to &quot;Funcionalidades&quot;">​</a></h2><ul><li><strong>Três serviços de origem</strong>: arranjo rápido (motor), chapa (carroçaria e pneus), reparação completa. O nome, o preço, a duração e as partes reparadas podem ser alterados. Veja <a href="/pt/repair-station/settings">Definições</a>.</li><li><strong>Preço consoante os danos</strong>: o preço acompanha os danos das partes reparadas, até uma percentagem mínima. Os veículos intactos são recusados.</li><li><strong>Editor de estações no jogo</strong>: crie uma estação onde está, mova a zona de paragem e um prop opcional com o teclado e guarde. Veja <a href="/pt/repair-station/stations">Estações</a>.</li><li><strong>Os mecânicos primeiro</strong>: as estações fecham enquanto houver mecânicos suficientes em serviço, e os jogadores chamam-nos a eles.</li><li><strong>Justo e seguro</strong>: um veículo por estação, verificações do condutor e da velocidade, pagamentos validados pelo servidor. Uma reparação cancelada é reembolsada na conta cobrada.</li><li><strong>Descontos por profissão</strong>, uma percentagem de preço por estação e pagamento em dinheiro, banco, ou dinheiro e depois banco.</li><li><strong>Tudo no <code>/nay</code></strong>: serviços, preços, estações, profissões de mecânico, blips com seletor visual de ícone e cor.</li><li><strong>API HTTP e webhooks</strong>: histórico de reparações, estatísticas e estações para o seu site ou bot, uma mensagem do Discord por cada reparação. Veja <a href="/pt/repair-station/api">API e webhooks</a>.</li><li><strong>Extensível</strong>: outro recurso pode alterar preços, fechar estações e participar em cada reparação. Veja <a href="/pt/repair-station/api#extensions">Extensões</a>.</li><li><strong>Seis idiomas</strong>: inglês, francês, espanhol, português, polaco, alemão.</li></ul><h2 id="compatibilidade" tabindex="-1">Compatibilidade <a class="header-anchor" href="#compatibilidade" aria-label="Permalink to &quot;Compatibilidade&quot;">​</a></h2><ul><li>Frameworks: ESX Legacy, QBCore, QBox, ox_core, detetados automaticamente.</li><li>Dependências: oxmysql e <code>nay_lib</code> (incluído na sua compra).</li></ul><h2 id="instalacao" tabindex="-1">Instalação <a class="header-anchor" href="#instalacao" aria-label="Permalink to &quot;Instalação&quot;">​</a></h2><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_repair</span></span></code></pre></div><p>Os passos completos estão na página <a href="/pt/getting-started">Primeiros passos</a>. Depois atribua-se <code>nay_repair.config</code> (ou <code>nay.admin</code>) e abra <code>/nay</code>. Três estações vêm prontas de origem: Hayes Autos, Sandy Shores e Paleto Bay.</p>`,9)])])}const g=e(i,[["render",t]]);export{u as __pageData,g as default};
